insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('rvb-minsk-027','menu','Old Fashioned',null,'{"id":"rvb-minsk-027","name":"Old Fashioned","category":"cocktails","ingredients":[{"name":"бурбон","amount":""},{"name":"биттер ангостура","amount":""},{"name":"тросниковый сахар","amount":""},{"name":"BonAqua","amount":""},{"name":"апельсин","amount":""}],"composition":"бурбон, биттер ангостура, тросниковый сахар, BonAqua, апельсин","volume":"250 мл","glass":"ОлдФешн","garnish":"Цедра апельсина","method":"","description":"Праотец всех коктейлей в современном понимании. Напиток для вдумчивого наслаждения, где главная звезда — виски, а остальные компоненты лишь подчёркивают его характер.","taste":"Богатый, крепкий, согревающий. Вкус напрямую зависит от выбранного виски: от ванильно-карамельных нот бурбона до дымных и фруктовых оттенков скотча","features":"","price":"30 р.","image":"","subcategory":"Классические","fact":"","characterSourcePage":9}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('rvb-minsk-029','menu','Clover Club',null,'{"id":"rvb-minsk-029","name":"Clover Club","category":"cocktails","ingredients":[{"name":"джин","amount":""},{"name":"малиновое пюре","amount":""},{"name":"белок","amount":""},{"name":"сок лимона","amount":""}],"composition":"джин, малиновое пюре, белок, сок лимона","volume":"300 мл","glass":"Шале","garnish":"Мята, суб. малина","method":"","description":"Элегантный и романтичный коктейль, названный в честь мужского клуба журналистов. Его визитная карточка — нежная малиновая пенка.","taste":"Нежный, сбалансированный, ягодно-цитрусовый","features":"","price":"25 р.","image":"","subcategory":"Классические","fact":"","characterSourcePage":10}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('rvb-minsk-031','menu','Negroni',null,'{"id":"rvb-minsk-031","name":"Negroni","category":"cocktails","ingredients":[{"name":"Вермут Rosso","amount":""},{"name":"Campari","amount":""},{"name":"джин","amount":""},{"name":"апельсин","amount":""}],"composition":"Вермут Rosso, Campari, джин, апельсин","volume":"300мл","glass":"ОлдФешн","garnish":"Цедра апельсина","method":"","description":"Абсолютная икона итальянского аперитива. Идеальный баланс силы, горечи и сладости, где три равных компонента ведут бесконечный диалог. Напиток характера, приобретающий глубину с каждым глотком.","taste":"Горький, травяной, сложный, согревающий","features":"","price":"30 р.","image":"","subcategory":"Классические","fact":"","characterSourcePage":10}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('rvb-minsk-030','menu','Moscow Mule',null,'{"id":"rvb-minsk-030","name":"Moscow Mule","category":"cocktails","ingredients":[{"name":"водка","amount":""},{"name":"лайм","amount":""},{"name":"имбирь","amount":""},{"name":"имбирный эль","amount":""},{"name":"медовый сироп","amount":""},{"name":"мята","amount":""}],"composition":"водка, лайм, имбирь, имбирный эль, медовый сироп, мята","volume":"450 мл","glass":"Кружка","garnish":"Свежая мята и лайм","method":"","description":"Блестящий пример маркетинга, породивший культ медной кружки. Освежающий, имбирно-пряный коктейль, который подчёркивает чистоту водки.","taste":"Острый, пряный, освежающий. Резкий имбирь, кислота лайма и нейтральная водка создают идеальный тандем.","features":"","price":"25 р.","image":"","subcategory":"Классические","fact":"","characterSourcePage":10}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
